//go:build arm64

package floats

// The NEON kernels of the DCT-IV twiddle passes (twiddle.go), generated by
// go-asmgen (twiddle_arm64_gen.go) into twiddle_arm64.s. The gather kernels do two
// complex numbers per step, (n/4)*2 of the n/2, and the Go code finishes the odd
// one; the scatter kernels do two from each end per step, cover every output when
// n >= 4 and write some twice with the same value, so they have no tail. NEON is
// the ARMv8-A baseline: no gate. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func cmulGather64NEON(dst, x, tw []float64)

//go:noescape
func cmulGatherFrom32NEON(dst []float64, x []float32, tw []float64)

//go:noescape
func cmulScatter64NEON(dst, c, tw []float64, f float64)

//go:noescape
func cmulScatterTo32NEON(dst []float32, c, tw []float64, f float64)

func cmulGather(dst, x, tw []float64) {
	cmulGather64NEON(dst, x, tw)
	cmulGatherTail(dst, x, tw, (len(tw)/2)&^1)
}

func cmulGather32(dst []float64, x []float32, tw []float64) {
	cmulGatherFrom32NEON(dst, x, tw)
	cmulGather32Tail(dst, x, tw, (len(tw)/2)&^1)
}

func cmulScatter(dst, c, tw []float64, f float64) {
	if len(tw) < 4 {
		cmulScatterRef(dst, c, tw, f)
		return
	}
	cmulScatter64NEON(dst, c, tw, f)
}

func cmulScatter32(dst []float32, c, tw []float64, f float64) {
	if len(tw) < 4 {
		cmulScatter32Ref(dst, c, tw, f)
		return
	}
	cmulScatterTo32NEON(dst, c, tw, f)
}
